import * as THREE from './vendor/three.module.js';
import { OrbitControls } from './vendor/OrbitControls.js';
const $=id=>document.getElementById(id), reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const renderer=new THREE.WebGLRenderer({canvas:$('scene'),antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0x191e1d);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.35;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.localClippingEnabled=true;
const scene=new THREE.Scene();scene.fog=new THREE.Fog(0x191e1d,1.5,3);
const camera=new THREE.PerspectiveCamera(39,1,.01,8);camera.position.set(.38,.36,.56);
const controls=new OrbitControls(camera,$('scene'));controls.target.set(0,.075,0);controls.enableDamping=true;controls.dampingFactor=.06;controls.minDistance=.28;controls.maxDistance=1.15;controls.maxPolarAngle=Math.PI*.49;controls.enablePan=false;controls.autoRotate=!reduced;controls.autoRotateSpeed=.45;controls.rotateSpeed=.65;controls.zoomSpeed=.65;$('rotate').checked=!reduced;
scene.add(new THREE.HemisphereLight(0xf8ecd6,0x394139,2.2));
function light(color,power,pos){const l=new THREE.DirectionalLight(color,power);l.position.set(...pos);scene.add(l);return l;}
const key=light(0xffe3bf,3,[.3,.75,.4]);key.castShadow=true;key.shadow.mapSize.set(1024,1024);Object.assign(key.shadow.camera,{left:-.5,right:.5,top:.5,bottom:-.5,near:.05,far:2});key.shadow.bias=-.0002;key.shadow.normalBias=.0005;
light(0xb4c7c0,1.1,[-.5,.25,.1]);light(0xffc08a,1.9,[0,.4,-.5]);
const root=new THREE.Group();root.rotation.x=-Math.PI/2;scene.add(root);
const plinth=new THREE.Mesh(new THREE.CylinderGeometry(.225,.235,.012,128),new THREE.MeshStandardMaterial({color:0x303b34,roughness:.94}));plinth.position.y=-.009;plinth.receiveShadow=true;scene.add(plinth);
const floor=new THREE.Mesh(new THREE.PlaneGeometry(10,10),new THREE.MeshStandardMaterial({color:0x191e1b,roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.016;floor.receiveShadow=true;scene.add(floor);
const rim=new THREE.Mesh(new THREE.TorusGeometry(.225,.0005,6,160),new THREE.MeshBasicMaterial({color:0x6e785f,transparent:true,opacity:.35}));rim.rotation.x=Math.PI/2;rim.position.y=-.0029;scene.add(rim);
let scan,full,lines,profile,ready=false,phase='scan',animation=null,traceProgress=0,buildProgress=0,sequenceToken=0;
const clip=new THREE.Plane(new THREE.Vector3(0,-1,0),-.01);
const chapters={scan:['01 / 03','La materia conservada','El escaneo recoge los fragmentos y la textura de la cerámica. Gira la pieza para explorar sus superficies.','ESCANEO ORIGINAL'],trace:['02 / 03','Las líneas de la forma','El perfil y las secciones dibujan una continuidad posible entre los fragmentos conservados.','TRAZADO GEOMÉTRICO'],rebuild:['03 / 03','Una forma recuperada','La superficie completa revela la restitución digital. Activa «Ver fragmentos» para comparar la hipótesis con la evidencia.','RESTITUCIÓN DIGITAL']};
function setChapter(p){phase=p;const c=chapters[p];$('chapterNumber').textContent=c[0];$('chapterTitle').textContent=c[1];$('chapterText').textContent=c[2];$('stageLabel').textContent=c[3];for(const id of ['scan','trace','rebuild']){$(id).classList.toggle('active',id===p);$(id).setAttribute('aria-current',id===p?'step':'false');}}
function buttons(busy=false){$('scan').disabled=!ready;$('trace').disabled=!ready||busy;$('rebuild').disabled=!ready||busy||traceProgress<1;$('demo').disabled=!ready||busy;}
function reset(){sequenceToken++;if(animation)animation.resolve(false);animation=null;traceProgress=buildProgress=0;scan.visible=true;scan.material.opacity=1;full.visible=lines.visible=false;full.material.opacity=1;full.material.depthWrite=true;$('compare').checked=false;$('compareLabel').hidden=true;$('progressFill').style.width='0%';setChapter('scan');buttons();$('status').textContent='Explora la pieza y pulsa Trazar para comenzar.';}
function animate(kind,duration){return new Promise(resolve=>{animation={kind,start:performance.now(),duration:reduced?150:duration,resolve};buttons(true);});}
async function trace(){if(!ready)return;animation=null;buildProgress=0;full.visible=false;scan.visible=true;scan.material.opacity=1;lines.visible=true;lines.material.opacity=.85;traceProgress=0;lines.geometry.setDrawRange(0,0);$('compareLabel').hidden=true;setChapter('trace');$('status').textContent='Trazando el perfil y las secciones…';await animate('trace',3800);}
async function rebuild(){if(!ready||traceProgress<1)return;setChapter('rebuild');full.visible=true;full.material.opacity=1;full.material.depthWrite=true;scan.visible=true;scan.material.opacity=1;$('compare').checked=false;buildProgress=0;clip.constant=-.008;$('status').textContent='Reconstruyendo la superficie desde la base…';await animate('rebuild',3400);}
function setComparison(){const compare=$('compare').checked;full.material.opacity=compare?.24:1;full.material.depthWrite=!compare;scan.visible=compare;scan.material.opacity=1;lines.visible=compare;lines.material.opacity=.18;}
$('scan').onclick=reset;$('trace').onclick=()=>{sequenceToken++;trace()};$('rebuild').onclick=()=>{sequenceToken++;rebuild()};$('compare').onchange=setComparison;
$('demo').onclick=async()=>{reset();const token=sequenceToken;await new Promise(r=>setTimeout(r,reduced?0:1000));if(token!==sequenceToken)return;await trace();if(token!==sequenceToken)return;await new Promise(r=>setTimeout(r,reduced?0:700));if(token!==sequenceToken)return;await rebuild();};
$('rotate').onchange=()=>controls.autoRotate=$('rotate').checked;
$('home').onclick=()=>{camera.position.set(.38,.36,.56);controls.target.set(0,.075,0);controls.update();};
$('fullscreen').onclick=async()=>{const el=document.querySelector('.viewer');try{if(document.fullscreenElement)await document.exitFullscreen();else if(el.requestFullscreen)await el.requestFullscreen();else{el.classList.toggle('expanded');document.body.classList.toggle('expanded');}}catch{el.classList.toggle('expanded');document.body.classList.toggle('expanded');}resize();};
addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('.viewer').classList.remove('expanded');document.body.classList.remove('expanded');resize();}});
$('scene').addEventListener('keydown',e=>{const v=camera.position.clone().sub(controls.target);if(e.key==='+'||e.key==='=')v.multiplyScalar(.9);else if(e.key==='-')v.multiplyScalar(1.1);else if(e.key==='ArrowLeft'||e.key==='ArrowRight')v.applyAxisAngle(new THREE.Vector3(0,1,0),e.key==='ArrowLeft'?.12:-.12);else return;e.preventDefault();v.clampLength(.28,1.15);camera.position.copy(controls.target).add(v);controls.update();});
function geometry(d){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(d.positions,3));g.setIndex(d.indices);g.computeVertexNormals();return g;}
function buildLines(){const segments=[];const add=(a,b)=>segments.push({a,b,z:(a[2]+b[2])/2});for(let n=0;n<16;n++){const t=n*Math.PI/8;for(let j=1;j<profile.length;j++){const a=profile[j-1],b=profile[j];add([a[0]*Math.cos(t),a[0]*Math.sin(t),a[1]],[b[0]*Math.cos(t),b[0]*Math.sin(t),b[1]]);}}const top=profile.reduce((best,p,i)=>p[1]>profile[best][1]?i:best,0);for(let j=8;j<=top;j+=3){const [r,z]=profile[j];for(let n=0;n<128;n++){const a=n*Math.PI/64,b=(n+1)*Math.PI/64;add([r*Math.cos(a),r*Math.sin(a),z],[r*Math.cos(b),r*Math.sin(b),z]);}}segments.sort((a,b)=>a.z-b.z);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(segments.flatMap(s=>[...s.a,...s.b]),3));g.setDrawRange(0,0);lines=new THREE.LineSegments(g,new THREE.LineBasicMaterial({color:0xf6cb86,transparent:true,opacity:.85,depthWrite:false}));lines.visible=false;root.add(lines);}
function ceramicMaterial(){const m=new THREE.MeshStandardMaterial({color:0xbd7250,roughness:.86,metalness:0,side:THREE.DoubleSide,clippingPlanes:[clip],clipShadows:true,transparent:true});m.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nvarying vec3 clayPosition;').replace('#include <begin_vertex>','#include <begin_vertex>\nclayPosition = position;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 clayPosition;').replace('#include <color_fragment>','#include <color_fragment>\nfloat grain=fract(sin(dot(floor(clayPosition*2400.0),vec3(12.9898,78.233,45.164)))*43758.5453);\nfloat bands=sin(clayPosition.z*3500.0)*0.012;\ndiffuseColor.rgb *= 0.94 + grain*0.12;');};return m;}
async function load(url,binary=false){const r=await fetch(url);if(!r.ok)throw Error('No se pudo cargar '+url);return binary?r.arrayBuffer():r.json();}
(async()=>{try{const [positions,uv,data,p,texture]=await Promise.all([load('./assets/scan-position.bin',true),load('./assets/scan-uv.bin',true),load('./assets/reconstruction.json'),load('./assets/profile.json'),new THREE.TextureLoader().loadAsync('./assets/scan-texture.png')]);profile=p;texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=Math.min(renderer.capabilities.getMaxAnisotropy(),8);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(positions),3));g.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(uv),2));g.computeVertexNormals();scan=new THREE.Mesh(g,new THREE.MeshStandardMaterial({map:texture,roughness:.94,side:THREE.DoubleSide,transparent:true}));scan.castShadow=scan.receiveShadow=true;root.add(scan);full=new THREE.Mesh(geometry(data),ceramicMaterial());full.castShadow=full.receiveShadow=true;full.visible=false;root.add(full);buildLines();ready=true;$('loading').remove();reset();}catch(e){$('loading').textContent='No se pudo cargar la pieza. Recarga para intentarlo de nuevo.';$('status').textContent=e.message;console.error(e);}})();
function resize(){const e=document.querySelector('.viewer'),w=e.clientWidth,h=e.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(document.querySelector('.viewer'));resize();
let last=performance.now();function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.05);last=now;if(animation){const a=animation,t=Math.min(1,(now-a.start)/a.duration),e=t*t*(3-2*t);$('progressFill').style.width=(e*100)+'%';if(a.kind==='trace'){traceProgress=t;const count=lines.geometry.attributes.position.count;lines.geometry.setDrawRange(0,Math.min(count,Math.floor(e*count/2)*2));}else{buildProgress=t;clip.constant=-.008+e*.18;scan.material.opacity=1-e;lines.material.opacity=.85*(1-e);if(t===1){scan.visible=false;lines.visible=false;$('compareLabel').hidden=false;}}if(t===1){animation=null;buttons();$('status').textContent=a.kind==='trace'?'Trazado completo. Pulsa Reconstruir para revelar la superficie.':'Restitución completa. Gira, acerca o compara con los fragmentos.';a.resolve();}}controls.update(dt);renderer.render(scene,camera);}requestAnimationFrame(frame);
window.__scene={getState:()=>({ready,phase,traceProgress,buildProgress,animating:!!animation,scanVisible:scan?.visible,fullVisible:full?.visible,linesVisible:lines?.visible,comparison:$('compare').checked,camera:camera.position.toArray(),triangles:renderer.info.render.triangles}),reset};
